import yaml

with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/registry.yaml') as f:
    reg = yaml.safe_load(f)

experiments = reg.get('experiments', {})

tau_sweep = []
bonus_seeds = []
ksweep = []
random_sel = []
obs_only = []
crm_always_on = []
reconvla = []
k2mean = []
other_done = []

for eid, exp in experiments.items():
    if exp.get('status') != 'DONE':
        continue
    conclusion = exp.get('conclusion', '')
    if conclusion not in ('success', 'negative'):
        continue

    metrics = exp.get('metrics', {}) or {}
    sr = metrics.get('overall_sr', metrics.get('success_rate', None))
    trigger = metrics.get('trigger_rate', None)
    spec = exp.get('spec', {}) or {}
    cmd = spec.get('command', '')

    # Categorize
    if 'tau' in eid and 'sweep' not in eid:
        # tau-sweep experiments
        # Extract tau, suite, seed from command or exp_id
        tau_val = None
        suite = None
        seed = None
        if '--conformal_threshold' in cmd:
            parts = cmd.split('--conformal_threshold')
            if len(parts) > 1:
                tau_val = parts[1].strip().split()[0]
        if '--benchmark' in cmd:
            parts = cmd.split('--benchmark')
            if len(parts) > 1:
                suite = parts[1].strip().split()[0]
        if '--seed' in cmd:
            parts = cmd.split('--seed')
            if len(parts) > 1:
                seed = parts[1].strip().split()[0]
        tau_sweep.append({'exp_id': eid, 'tau': tau_val, 'suite': suite, 'seed': seed, 'sr': sr, 'trigger_rate': trigger, 'conclusion': conclusion})
    elif 'ksweep' in eid or 'k20' in eid or 'k5' in eid.lower():
        ksweep.append({'exp_id': eid, 'sr': sr, 'conclusion': conclusion})
    elif 'random' in eid.lower() and 'selection' in eid.lower():
        random_sel.append({'exp_id': eid, 'sr': sr, 'conclusion': conclusion})
    elif 'obs-only' in eid or 'obs_only' in eid or ('crm_obs_only' in cmd and 'always-on' not in eid and 'crm-always' not in eid):
        obs_only.append({'exp_id': eid, 'sr': sr, 'conclusion': conclusion})
    elif 'always-on' in eid or 'always_on' in eid:
        crm_always_on.append({'exp_id': eid, 'sr': sr, 'conclusion': conclusion})
    elif 'reconvla' in eid:
        reconvla.append({'exp_id': eid, 'sr': sr, 'conclusion': conclusion})
    elif 'k2mean' in eid or 'k2-mean' in eid:
        k2mean.append({'exp_id': eid, 'sr': sr, 'conclusion': conclusion})
    elif 'supp' in eid or 'bonus' in eid:
        bonus_seeds.append({'exp_id': eid, 'sr': sr, 'conclusion': conclusion})

